impl Label {
    pub fn of(hat: Option<&str>, skill: Option<&str>) -> Result<Label, CommandError> {
        debug_assert!(
            hat.is_some() || skill.is_some(),
            "Label.of: a hat or a skill"
        );
        let result: Result<Label, CommandError> = todo!("Label.of");
        debug_assert!(
            result
                .as_ref()
                .map_or(true, |l| l.0 == hat.or(skill).unwrap_or_default()),
            "Label.of: the hat, else the skill"
        );
        debug_assert!(
            result.as_ref().map_or(true, |l| safe_name(&l.0)),
            "Label.of: only letters, digits, - and _"
        );
        result
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }
}

