    todo!("safe_name")
}

pub fn compose(role: Option<&str>, hat: Option<&str>, skill: Option<&str>) -> String {
    let result: String = todo!("compose");
    debug_assert!(
        in_order(&result, &[role, hat, skill]),
        "compose: role, hat, skill in this order"
    );
    debug_assert!(
        !result.split(SEPARATOR).any(|b| b.trim().is_empty()) || result.is_empty(),
        "compose: no blank block"
    );
    result
}

